def norm(comp):
    rs=min(i for i,j in comp); cc=min(j for i,j in comp)
    rel=tuple(sorted((i-rs,j-cc) for i,j in comp))
    rows=sorted({r for r,c in rel}); cols=sorted({c for r,c in rel})
    pic=[''.join('#' if (rr,cc_) in set(rel) else '.' for cc_ in cols) for rr in rows]
    return tuple(pic),len(rel),(rs,cc)
